<template>
  <div class="container-fluid px-0">
    <div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h4 class="mb-1">Production Readiness</h4><div class="text-muted small">Operational health, release records, security events and recovery drills</div></div><button class="btn btn-success" :disabled="checking" @click="runChecks"><i class="bi bi-heart-pulse me-1"></i>{{checking?'Checking…':'Run health checks'}}</button></div>
    <div v-if="overview.latest_snapshot" class="card border-0 shadow-sm mb-3"><div class="card-body"><div class="d-flex justify-content-between align-items-center"><div><div class="text-muted small">Latest system status</div><h3 class="mb-0 text-capitalize">{{overview.latest_snapshot.overall_status}}</h3><div class="small text-muted">{{overview.latest_snapshot.checked_at}}</div></div><span class="badge fs-6" :class="statusClass(overview.latest_snapshot.overall_status)">{{overview.latest_snapshot.overall_status}}</span></div><div class="row g-2 mt-3"><div v-for="(check,key) in overview.latest_snapshot.checks" :key="key" class="col-12 col-md-6 col-xl-4"><div class="border rounded p-3 h-100"><div class="d-flex justify-content-between"><strong class="text-capitalize">{{key}}</strong><span class="badge" :class="statusClass(check.status)">{{check.status}}</span></div><div class="small text-muted mt-1">{{check.message}}</div></div></div></div></div></div>
    <div class="row g-3"><div class="col-12 col-xl-6"><div class="card border-0 shadow-sm h-100"><div class="card-header bg-white fw-semibold">Deployment release history</div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Version</th><th>Environment</th><th>Status</th><th>Deployed</th></tr></thead><tbody><tr v-for="r in overview.releases||[]" :key="r.id"><td>{{r.version}}</td><td>{{r.environment}}</td><td>{{r.status}}</td><td>{{r.deployed_at||'—'}}</td></tr><tr v-if="!overview.releases?.length"><td colspan="4" class="text-center text-muted py-3">No release records.</td></tr></tbody></table></div></div></div>
      <div class="col-12 col-xl-6"><div class="card border-0 shadow-sm h-100"><div class="card-header bg-white fw-semibold">Disaster recovery drills</div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Reference</th><th>Environment</th><th>Result</th><th>Completed</th></tr></thead><tbody><tr v-for="d in overview.recovery_drills||[]" :key="d.id"><td>{{d.drill_reference}}</td><td>{{d.environment}}</td><td>{{d.result}}</td><td>{{d.completed_at||'—'}}</td></tr><tr v-if="!overview.recovery_drills?.length"><td colspan="4" class="text-center text-muted py-3">No recovery drills recorded.</td></tr></tbody></table></div></div></div></div>
    <div class="card border-0 shadow-sm mt-3"><div class="card-header bg-white fw-semibold">Recent security events</div><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Event</th><th>Email</th><th>IP address</th><th>Date</th></tr></thead><tbody><tr v-for="e in securityEvents" :key="e.id"><td>{{e.event_type}}</td><td>{{e.email||'—'}}</td><td>{{e.ip_address||'—'}}</td><td>{{e.created_at}}</td></tr><tr v-if="!securityEvents.length"><td colspan="4" class="text-center text-muted py-3">No security events recorded.</td></tr></tbody></table></div></div>
    <div class="alert alert-warning mt-3 small mb-0">These checks are operational indicators, not a penetration test, formal compliance audit or proof of disaster-recovery readiness. Perform restore drills in an isolated staging environment.</div>
  </div>
</template>
<script setup>
import { onMounted,ref } from 'vue';import api from '../api';
const overview=ref({}),securityEvents=ref([]),checking=ref(false);
const statusClass=s=>s==='healthy'||s==='ok'?'text-bg-success':s==='critical'?'text-bg-danger':'text-bg-warning';
async function load(){const [o,e]=await Promise.all([api.get('/system-readiness/overview'),api.get('/system-readiness/security-events')]);overview.value=o.data;securityEvents.value=e.data.data||[]}
async function runChecks(){checking.value=true;try{await api.post('/system-readiness/run-checks');await load()}finally{checking.value=false}}
onMounted(load);
</script>
